import React, { useState, useEffect } from "react"
import { graphql, navigate } from "gatsby"

import Layout from "components/Layout"
import SEO from "components/SEO"
import PostList from "components/PostList"
import VerticalSpace from "components/VerticalSpace"
import TagList from "components/TagList"
import styled from "styled-components"

const TagsPageContainer = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
`

const FilterInfo = styled.div`
  margin-bottom: 24px;
  padding: 16px;
  background: ${props => props.theme?.colors?.background || '#f8fafc'};
  border-radius: 12px;
  border: 1px solid ${props => props.theme?.colors?.border || '#e5e7eb'};
  
  h3 {
    margin: 0 0 8px 0;
    color: ${props => props.theme?.colors?.text || '#1a1a1a'};
    font-size: 18px;
  }
  
  p {
    margin: 0;
    color: ${props => props.theme?.colors?.secondaryText || '#6b7280'};
    font-size: 14px;
  }
`

const ClearButton = styled.button`
  background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
  color: white;
  border: none;
  padding: 8px 16px;
  border-radius: 8px;
  font-size: 14px;
  cursor: pointer;
  transition: all 0.3s ease;
  margin-top: 8px;
  
  &:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.3);
  }
`

const TagsPage = React.memo(({ data, location }) => {
  const allPosts = data.allMarkdownRemark.nodes
  const tagGroups = data.allMarkdownRemark.group
  const [selectedTag, setSelectedTag] = useState(null)
  const [filteredPosts, setFilteredPosts] = useState(allPosts)

  useEffect(() => {
    // URL 쿼리 파라미터에서 태그 추출
    const urlParams = new URLSearchParams(location.search)
    const tagFromUrl = urlParams.get('q')
    
    if (tagFromUrl) {
      const decodedTag = decodeURIComponent(tagFromUrl)
      setSelectedTag(decodedTag)
      filterPostsByTag(decodedTag)
    } else {
      setSelectedTag(null)
      setFilteredPosts(allPosts)
    }
  }, [location.search, allPosts])

  const filterPostsByTag = (tag) => {
    if (!tag) {
      setFilteredPosts(allPosts)
      return
    }
    
    const filtered = allPosts.filter(post => 
      post.frontmatter.tags && post.frontmatter.tags.includes(tag)
    )
    setFilteredPosts(filtered)
  }

  const handleTagClick = (tag) => {
    setSelectedTag(tag)
    filterPostsByTag(tag)
    
    // URL 업데이트
    const newUrl = tag ? `/tags?q=${encodeURIComponent(tag)}` : '/tags'
    window.history.pushState({}, '', newUrl)
  }

  const handleClearFilter = () => {
    setSelectedTag(null)
    setFilteredPosts(allPosts)
    navigate('/')
  }

  return (
    <Layout>
      <SEO title={selectedTag ? `${selectedTag} 태그` : "Tags"} />
      <VerticalSpace size={48} />
      <TagsPageContainer>
        {/* 태그 목록 - 태그가 선택되지 않았을 때는 숨김 */}
        {selectedTag && (
          <TagList 
            tagList={tagGroups} 
            count={true}
            selected={selectedTag}
            onClick={handleTagClick}
          />
        )}
        
        {/* 현재 필터 정보 */}
        {selectedTag && (
          <FilterInfo>
            <h3>#{selectedTag}</h3>
            <p>{filteredPosts.length}개의 포스트</p>
            <ClearButton onClick={handleClearFilter}>
              모든 포스트 보기
            </ClearButton>
          </FilterInfo>
        )}
        
        {/* 포스트 목록 */}
        <PostList postList={filteredPosts} />
      </TagsPageContainer>
    </Layout>
  )
})

export default TagsPage

export const pageQuery = graphql`
  query {
    site {
      siteMetadata {
        title
      }
    }
    allMarkdownRemark(
      sort: { frontmatter: { date: DESC } }
      filter: { fileAbsolutePath: { regex: "/contents/posts/" } }
    ) {
      group(field: { frontmatter: { tags: SELECT } }) {
        fieldValue
        totalCount
      }
      nodes {
        excerpt(pruneLength: 200, truncate: true)
        html
        fields {
          slug
          readingTime {
            minutes
          }
        }
        frontmatter {
          date
          update
          title
          tags
          thumbnail {
            publicURL
          }
        }
      }
    }
  }
`
